def pre_filter_model_query(source):
    from suggestion_proposal_scope_contract import pre_suggestion_proposal
    source = pre_suggestion_proposal(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_filter_model_query_bytes(path):
    data = path.read_bytes()
    return pre_filter_model_query(data.decode()).encode() if path.suffix == '.swift' else data

